using DotLLM.Vulkan.Interop;

namespace DotLLM.Vulkan.Kernels;

/// <summary>
/// Record-STRIDED expert-bank kernels (Edge0 G3, #1981): the indexed MMVQ and the grouped coopmat kernels for Q3_K and IQ4_NL banks whose experts are
/// NOT contiguous. An Edge0 pack keeps each expert as one fixed-size record (gate | up | down); a projection is the array of those records read with a
/// byte stride, starting <c>baseOffset</c> bytes into record 0. The shaders (<c>*_strided.comp</c>, generated by <c>gen_moe_strided.py</c>) are the
/// unmodified contiguous shaders with the row base <c>baseOffset + e * expertStride + m * rowBytes</c>, so the mmap'd pack is imported once and read in place.
/// </summary>
internal static class MoeStridedFormats
{
    public static bool Supports(MoeIqQuant q) => q is MoeIqQuant.Q3_K or MoeIqQuant.IQ4_NL;

    public static string IndexedSpv(MoeIqQuant q) => q switch
    {
        MoeIqQuant.Q3_K => "moe_indexed_matmul_q3_k_mmvq_strided",
        MoeIqQuant.IQ4_NL => "moe_indexed_matmul_iq4_nl_mmvq_v2_strided",
        _ => throw new ArgumentOutOfRangeException(nameof(q), "no strided bank kernel for this format"),
    };

    public static string GroupedSpv(MoeIqQuant q) => q switch
    {
        MoeIqQuant.Q3_K => "moe_grouped_matmul_q3_k_coopmat_m64_strided",
        MoeIqQuant.IQ4_NL => "moe_grouped_matmul_iq4_nl_coopmat_m64_strided",
        _ => throw new ArgumentOutOfRangeException(nameof(q), "no strided bank kernel for this format"),
    };
}

/// <summary>Indexed (decode / small-batch) strided MMVQ: <c>y[n, m] = sum_k dequant(bank[baseOffset + indices[n] * stride + m * rowBytes + ...]) * x[n, k]</c> through dp4a.</summary>
internal sealed class MoeIndexedStridedMmvqKernel : IDisposable
{
    private const int Buffers = 5, PushBytes = 8 * sizeof(uint);
    private readonly VulkanDevice _device;
    private readonly VulkanModule _module;
    private readonly ComputePipeline _pipeline;
    private readonly nint _pool;
    private readonly DescriptorSetCache _cache;
    private bool _disposed;

    /// <summary>Bank format.</summary>
    public MoeIqQuant Quant { get; }

    private MoeIndexedStridedMmvqKernel(MoeIqQuant q, VulkanDevice d, VulkanModule m, ComputePipeline p, nint pool)
    {
        Quant = q; _device = d; _module = m; _pipeline = p; _pool = pool;
        _cache = new DescriptorSetCache(d, pool, p, buffersPerSet: Buffers);
    }

    /// <summary>Loads the strided shader for <paramref name="quant"/>; null without integer dot product or when the SPIR-V is missing / wave32 cannot be pinned on a narrower device.</summary>
    public static MoeIndexedStridedMmvqKernel? TryCreate(VulkanDevice device, string spvDir, MoeIqQuant quant)
    {
        if (!MoeStridedFormats.Supports(quant) || !device.HasIntegerDotProduct) return null;
        if (Wave32SubgroupControl.RequiredSubgroupSizeFor(device) == 0 && device.SubgroupSize < 32) return null;
        string path = Path.Combine(spvDir, MoeStridedFormats.IndexedSpv(quant) + ".spv");
        if (!File.Exists(path)) return null;
        var module = VulkanModule.LoadFromFile(device, path);
        ComputePipeline pipeline;
        try
        {
            Span<VkDescriptorBinding> b = stackalloc VkDescriptorBinding[Buffers];
            for (int i = 0; i < Buffers; i++) b[i] = new VkDescriptorBinding((uint)i);
            pipeline = module.CreateComputePipeline("main", b, PushBytes, requiredSubgroupSize: Wave32SubgroupControl.RequiredSubgroupSizeFor(device));
        }
        catch { module.Dispose(); throw; }
        return new MoeIndexedStridedMmvqKernel(quant, device, module, pipeline, KernelSupport.CreateDescriptorPool(device, buffersPerSet: Buffers));
    }

    internal void InvalidateDescriptorCache() => _cache.Reset();

    /// <summary>Records the dispatch. <paramref name="bank"/> holds the record array; <paramref name="expertStrideBytes"/> is the record size and <paramref name="baseOffsetBytes"/> the projection's offset in it.</summary>
    public unsafe void Record(nint cmd, VulkanDevice.Buffer bank, VulkanDevice.Buffer xq, VulkanDevice.Buffer xds, VulkanDevice.Buffer indices, VulkanDevice.Buffer y,
        int m, int k, int n, int numExperts, long expertStrideBytes, long baseOffsetBytes, int xDiv = 1)
    {
        var (blockBytes, group) = MoeIqFormats.Describe(Quant);
        if (m <= 0 || k <= 0 || n <= 0 || numExperts <= 0 || xDiv <= 0) throw new ArgumentOutOfRangeException(nameof(m));
        if ((k % group) != 0) throw new ArgumentException($"k must be a multiple of {group} for {Quant}, got {k}", nameof(k));
        int blocksPerRow = k / group;
        long rowBytes = (long)blocksPerRow * blockBytes;
        long need = baseOffsetBytes + (long)(numExperts - 1) * expertStrideBytes + (long)m * rowBytes;
        if (need > uint.MaxValue) throw new ArgumentException($"bank span is {need} bytes; the shader addresses it with 32-bit byte offsets.", nameof(bank));
        if (bank.Size < need) throw new ArgumentException("bank buffer too small.", nameof(bank));
        if (expertStrideBytes < (long)m * rowBytes) throw new ArgumentException("expert stride is smaller than one projection.", nameof(expertStrideBytes));
        int xRows = (n + xDiv - 1) / xDiv;
        if (xq.Size < QuantizeQ8_1RowsKernel.PackedBytes(xRows, k)) throw new ArgumentException("Packed activation buffer too small.", nameof(xq));
        if (xds.Size < QuantizeQ8_1RowsKernel.ScaleBytes(xRows, k)) throw new ArgumentException("Activation scale buffer too small.", nameof(xds));
        if (indices.Size < (long)n * sizeof(int)) throw new ArgumentException("indices buffer too small.", nameof(indices));
        if (y.Size < (long)n * m * sizeof(float)) throw new ArgumentException("y buffer too small.", nameof(y));

        Span<nint> buffers = stackalloc nint[Buffers] { bank.Handle, xq.Handle, xds.Handle, indices.Handle, y.Handle };
        nint set = _cache.GetOrCreate(buffers);
        VulkanApi.vkCmdBindPipeline(cmd, VkPipelineBindPoint.Compute, _pipeline.Pipeline);
        VulkanApi.vkCmdBindDescriptorSets(cmd, VkPipelineBindPoint.Compute, _pipeline.Layout, 0, 1, set, 0, 0);
        Span<uint> pc = stackalloc uint[8] { (uint)m, (uint)k, (uint)n, (uint)numExperts, (uint)blocksPerRow, (uint)xDiv, (uint)expertStrideBytes, (uint)baseOffsetBytes };
        fixed (uint* p = pc) VulkanApi.vkCmdPushConstants(cmd, _pipeline.Layout, VkShaderStageFlags.Compute, 0, PushBytes, (nint)p);
        VulkanApi.vkCmdDispatch(cmd, (uint)m, (uint)n, 1);
    }

    /// <inheritdoc/>
    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        if (_pool != 0) VulkanApi.vkDestroyDescriptorPool(_device.Handle, _pool, 0);
        _pipeline.Dispose();
        _module.Dispose();
    }
}

/// <summary>Grouped (prefill) strided coopmat kernel: the contiguous 16-row / 64-output-row wave64 shader with the record-strided row base.</summary>
internal sealed class MoeGroupedStridedCoopmatKernel : IDisposable
{
    private const int Buffers = 4, PushBytes = 10 * sizeof(uint), TileM = 64, TileN = 16;
    private readonly VulkanDevice _device;
    private readonly VulkanModule _module;
    private readonly ComputePipeline _pipeline;
    private readonly nint _pool;
    private readonly DescriptorSetCache _cache;
    private bool _disposed;

    /// <summary>Bank format.</summary>
    public MoeIqQuant Quant { get; }

    /// <summary>Token rows per workgroup (the indirect tile list is built with this).</summary>
    public int RowTile => TileN;

    /// <summary>Weight-row tiles per workgroup column for an output width <paramref name="m"/>.</summary>
    public int MTiles(int m) => (m + TileM - 1) / TileM;

    private MoeGroupedStridedCoopmatKernel(MoeIqQuant q, VulkanDevice d, VulkanModule m, ComputePipeline p, nint pool)
    {
        Quant = q; _device = d; _module = m; _pipeline = p; _pool = pool;
        _cache = new DescriptorSetCache(d, pool, p, buffersPerSet: Buffers);
    }

    /// <summary>True when cooperative matrices, native wave64 and the SPIR-V are available.</summary>
    public static bool IsSupportedOn(VulkanDevice device, string spvDir, MoeIqQuant quant)
        => MoeStridedFormats.Supports(quant) && device.HasCooperativeMatrix && device.SubgroupSize == 64
           && File.Exists(Path.Combine(spvDir, MoeStridedFormats.GroupedSpv(quant) + ".spv"));

    /// <summary>Creates the kernel (see <see cref="IsSupportedOn"/>).</summary>
    public static MoeGroupedStridedCoopmatKernel Create(VulkanDevice device, string spvDir, MoeIqQuant quant)
    {
        if (!IsSupportedOn(device, spvDir, quant)) throw new InvalidOperationException("Strided grouped kernel needs cooperative matrices, native wave64 and the SPIR-V.");
        var module = VulkanModule.LoadFromFile(device, Path.Combine(spvDir, MoeStridedFormats.GroupedSpv(quant) + ".spv"));
        ComputePipeline pipeline;
        try
        {
            Span<VkDescriptorBinding> b = stackalloc VkDescriptorBinding[Buffers];
            for (int i = 0; i < Buffers; i++) b[i] = new VkDescriptorBinding((uint)i);
            pipeline = module.CreateComputePipeline("main", b, PushBytes, requiredSubgroupSize: 0);
        }
        catch { module.Dispose(); throw; }
        return new MoeGroupedStridedCoopmatKernel(quant, device, module, pipeline, KernelSupport.CreateDescriptorPool(device, buffersPerSet: Buffers));
    }

    internal void InvalidateDescriptorCache() => _cache.Reset();

    private void Validate(VulkanDevice.Buffer bank, VulkanDevice.Buffer packedInput, VulkanDevice.Buffer output, int m, int k, int rows, int numExperts,
        long strideBytes, long baseBytes, out long rowBytes)
    {
        var (blockBytes, group) = MoeIqFormats.Describe(Quant);
        int kGroup = Math.Max(group, 64);
        if (m <= 0 || rows <= 0 || numExperts <= 0) throw new ArgumentOutOfRangeException(nameof(m));
        if (k <= 0 || (k % kGroup) != 0) throw new ArgumentException($"k must be a positive multiple of {kGroup} for {Quant}, got {k}", nameof(k));
        rowBytes = (long)(k / group) * blockBytes;
        long need = baseBytes + (long)(numExperts - 1) * strideBytes + (long)m * rowBytes;
        if (need > uint.MaxValue) throw new ArgumentException($"bank span is {need} bytes; the shader addresses it with 32-bit byte offsets.", nameof(bank));
        if (bank.Size < need) throw new ArgumentException("bank buffer too small.", nameof(bank));
        if (strideBytes < (long)m * rowBytes) throw new ArgumentException("expert stride is smaller than one projection.", nameof(strideBytes));
        if (packedInput.Size < (long)rows * k * sizeof(float)) throw new ArgumentException("packedInput buffer too small.", nameof(packedInput));
        if (output.Size < (long)rows * m * sizeof(float)) throw new ArgumentException("output buffer too small.", nameof(output));
    }

    /// <summary>Synchronous launch on the legacy 3-D grid (tests).</summary>
    public void Launch(VulkanDevice.Buffer bank, VulkanDevice.Buffer packedInput, VulkanDevice.Buffer offsets, VulkanDevice.Buffer output,
        int m, int k, int rows, int numExperts, long expertStrideBytes, long baseOffsetBytes, int maxRowsPerExpert = 0)
    {
        using var ctx = _device.CreateSubmitContext();
        ctx.Begin();
        Record(ctx.CommandBuffer, bank, packedInput, offsets, output, m, k, rows, numExperts, expertStrideBytes, baseOffsetBytes, maxRowsPerExpert);
        ctx.SubmitAndWait();
    }

    /// <summary>Legacy-grid launch.</summary>
    public unsafe void Record(nint cmd, VulkanDevice.Buffer bank, VulkanDevice.Buffer packedInput, VulkanDevice.Buffer offsets, VulkanDevice.Buffer output,
        int m, int k, int rows, int numExperts, long expertStrideBytes, long baseOffsetBytes, int maxRowsPerExpert = 0)
    {
        Validate(bank, packedInput, output, m, k, rows, numExperts, expertStrideBytes, baseOffsetBytes, out long rowBytes);
        if (offsets.Size < (long)(numExperts + 1) * sizeof(uint)) throw new ArgumentException("offsets buffer too small.", nameof(offsets));
        Bind(cmd, bank, packedInput, offsets, output, m, k, rows, numExperts, rowBytes, expertStrideBytes, baseOffsetBytes, 0);
        int rowTiles = maxRowsPerExpert > 0 ? Math.Min(maxRowsPerExpert, rows) : rows;
        VulkanApi.vkCmdDispatch(cmd, (uint)MTiles(m), (uint)((rowTiles + TileN - 1) / TileN), (uint)numExperts);
    }

    /// <summary>Indirect launch over the tile list <see cref="MoeBuildTileListKernel"/> wrote after the offsets.</summary>
    public unsafe void RecordIndirect(nint cmd, VulkanDevice.Buffer bank, VulkanDevice.Buffer packedInput, VulkanDevice.Buffer offsetsAndTiles, VulkanDevice.Buffer output,
        VulkanDevice.Buffer dispatchArgs, int dispatchArgsOffset, int m, int k, int rows, int numExperts, long expertStrideBytes, long baseOffsetBytes)
    {
        Validate(bank, packedInput, output, m, k, rows, numExperts, expertStrideBytes, baseOffsetBytes, out long rowBytes);
        if (dispatchArgs.Size < dispatchArgsOffset + 3 * sizeof(uint)) throw new ArgumentException("dispatchArgs buffer too small.", nameof(dispatchArgs));
        if (offsetsAndTiles.Size < MoeBuildTileListKernel.OffsetsBufferUints(numExperts, rows) * sizeof(uint)) throw new ArgumentException("offsets/tile-list buffer too small.", nameof(offsetsAndTiles));
        Bind(cmd, bank, packedInput, offsetsAndTiles, output, m, k, rows, numExperts, rowBytes, expertStrideBytes, baseOffsetBytes, (uint)(numExperts + 1));
        VulkanApi.vkCmdDispatchIndirect(cmd, dispatchArgs.Handle, (ulong)dispatchArgsOffset);
    }

    private unsafe void Bind(nint cmd, VulkanDevice.Buffer bank, VulkanDevice.Buffer x, VulkanDevice.Buffer offsets, VulkanDevice.Buffer y,
        int m, int k, int rows, int numExperts, long rowBytes, long stride, long baseOff, uint tileList)
    {
        Span<nint> buffers = stackalloc nint[Buffers] { bank.Handle, x.Handle, offsets.Handle, y.Handle };
        nint set = _cache.GetOrCreate(buffers);
        VulkanApi.vkCmdBindPipeline(cmd, VkPipelineBindPoint.Compute, _pipeline.Pipeline);
        VulkanApi.vkCmdBindDescriptorSets(cmd, VkPipelineBindPoint.Compute, _pipeline.Layout, 0, 1, set, 0, 0);
        Span<uint> pc = stackalloc uint[10] { (uint)m, (uint)k, (uint)rows, (uint)numExperts, (uint)(k / 32), (uint)rowBytes, tileList, 0u, (uint)stride, (uint)baseOff };
        fixed (uint* p = pc) VulkanApi.vkCmdPushConstants(cmd, _pipeline.Layout, VkShaderStageFlags.Compute, 0, PushBytes, (nint)p);
    }

    /// <inheritdoc/>
    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        if (_pool != 0) VulkanApi.vkDestroyDescriptorPool(_device.Handle, _pool, 0);
        _pipeline.Dispose();
        _module.Dispose();
    }
}
